using System.Text.Encodings.Web;
using System.Text.Json;

var opt = new JsonSerializerOptions {
  PropertyNamingPolicy =
    JsonNamingPolicy.CamelCase,
  Encoder = JavaScriptEncoder
    .UnsafeRelaxedJsonEscaping };
var s = new Schueler("Lena Grün", 1);
string text = JsonSerializer.Serialize(s, opt);
Console.WriteLine(text);
// {"name":"Lena Grün","note":1}
var back = JsonSerializer
  .Deserialize<Schueler>(text, opt)!;
Console.WriteLine(back.Note + 1);  // 2
var d = new Dictionary<int, string>
  { [1] = "a" };
Console.WriteLine(JsonSerializer.Serialize(d));
// {"1":"a"}

record Schueler(string Name, int Note);

using System.Xml.Linq;

var xml = """
  <klasse name="5AHIF">
    <schueler note="1">Lena</schueler>
    <schueler note="3">Jonas</schueler>
  </klasse>
  """;
var root = XElement.Parse(xml);
Console.WriteLine(root.Attribute("name")?.Value);
foreach (var s in root.Elements("schueler"))
  Console.WriteLine(
    $"{s.Value} {(int)s.Attribute("note")!}");
// 5AHIF
// Lena 1
// Jonas 3

using System.Globalization;
using System.Text;
using Microsoft.VisualBasic.FileIO;

var zeile = "\"Huber; Anna\";12,50";
Console.WriteLine(zeile.Split(';').Length);
// 3  -> falsch zerlegt!
using var p = new TextFieldParser(
  new StringReader(zeile));
p.SetDelimiters(";");
p.HasFieldsEnclosedInQuotes = true;
var f = p.ReadFields()!;
var nf = new NumberFormatInfo
  { NumberDecimalSeparator = "," };
var betrag = decimal.Parse(f[1], nf);
Console.WriteLine(f[0]);  // Huber; Anna
Console.WriteLine(betrag == 12.5m); // True

var b = Encoding.UTF8.GetBytes("Jänner");
Console.WriteLine(b.Length);   // 7
Console.WriteLine(Encoding.Latin1.GetString(b));
// JÃ¤nner

var t = DateTimeOffset.Parse(
  "2026-07-01T08:30:00+00:00");
var tz = TimeZoneInfo
  .FindSystemTimeZoneById("Europe/Vienna");
var wien = TimeZoneInfo.ConvertTime(t, tz);
Console.WriteLine(wien.ToString("o"));
// 2026-07-01T10:30:00.0000000+02:00
Console.WriteLine(t == wien);   // True

